/*
 * Agentic Company Research
 * Gemini calls web_search / web_fetch tools autonomously until it has
 * enough data to produce the structured intel JSON.
 * Max 10 tool-call rounds to prevent runaway loops.
 */
const { company_name = '', website_url = '', linkedin_url = '' } = $input.item.json;
const API_KEY = $vars.GOOGLE_API_KEY;
const MODEL = 'gemini-2.5-flash-lite';
const MAX_ROUNDS = 10;
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';

if (!API_KEY) throw new Error('GOOGLE_API_KEY not set in n8n Variables');

// ── Tool implementations ────────────────────────────────────────────────────
async function web_search({ query }) {
  const url = `https://lite.duckduckgo.com/lite/?q=${encodeURIComponent(query)}`;
  const html = await fetch(url, {
    headers: { 'User-Agent': UA, Accept: 'text/html' },
    signal: AbortSignal.timeout(12000),
  }).then(r => r.text()).catch(e => '');

  const links = [...html.matchAll(/href="(https?:\/\/[^"]+)"/g)]
    .map(m => m[1]).filter(u => !u.includes('duckduckgo')).slice(0, 5);
  const snippets = [...html.matchAll(/class='result-snippet'>([\s\S]+?)<\/td>/g)]
    .slice(0, 6).map(m => m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim());

  return [
    `Search results for: ${query}`,
    ...snippets.map((s, i) => `[${i+1}] ${s}${links[i] ? ' — ' + links[i] : ''}`),
  ].join('\n');
}

async function web_fetch({ url }) {
  // Basic SSRF guard
  const hostname = new URL(url).hostname;
  if (/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(hostname)) {
    return 'Error: private/loopback addresses are not allowed';
  }
  const html = await fetch(url, {
    headers: { 'User-Agent': UA },
    signal: AbortSignal.timeout(15000),
  }).then(r => r.text()).catch(e => `Fetch error: ${e.message}`);

  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);
}

// ── Tool dispatch ───────────────────────────────────────────────────────────
async function executeTool(name, args) {
  if (name === 'web_search') return web_search(args);
  if (name === 'web_fetch')  return web_fetch(args);
  return `Unknown tool: ${name}`;
}

// ── Gemini API call ─────────────────────────────────────────────────────────
async function callGemini(messages) {
  const body = {
    contents: messages,
    tools: [{
      functionDeclarations: [
        {
          name: 'web_search',
          description: 'Search the web using DuckDuckGo. Returns titles, snippets, and URLs.',
          parameters: {
            type: 'object',
            properties: {
              query: { type: 'string', description: 'The search query' },
            },
            required: ['query'],
          },
        },
        {
          name: 'web_fetch',
          description: 'Fetch and read the text content of a public web page.',
          parameters: {
            type: 'object',
            properties: {
              url: { type: 'string', description: 'Full URL including https://' },
            },
            required: ['url'],
          },
        },
      ],
    }],
    generationConfig: {
      temperature: 0.1,
      maxOutputTokens: 4096,
    },
  };

  const res = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${API_KEY}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30000),
    }
  );

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Gemini API ${res.status}: ${err.slice(0, 300)}`);
  }
  return res.json();
}

// ── Research prompt ─────────────────────────────────────────────────────────
const RESEARCH_PROMPT = `You are a B2B sales intelligence analyst for Zenduit (fleet telematics).
Research the company below thoroughly using your tools, then return a structured JSON object.

Company: ${company_name}
Website: ${website_url || 'unknown — search for it'}
LinkedIn: ${linkedin_url || 'unknown'}

Zenduit products: ZenduONE (unified GPS+compliance+driver behavior), ZenduCAM (AI dashcam,
event recording, coaching), ZenduFuel (fuel monitoring + theft detection),
ZenduMaintenance (predictive scheduling), ZenduIQ (analytics dashboard).
Target industries: trucking/LTL, construction, oil & gas, public works, distribution/logistics.
Key ROI: 12% idle reduction, 18% insurance savings, 8% fuel savings.

Steps:
1. Fetch the company website to understand what they do, fleet size, industries, locations.
2. Search for recent news: funding, expansion, leadership changes, acquisitions, hiring.
3. Search for their current fleet management tools / telematics competitors they use.
4. Check LinkedIn or careers page for fleet-related job postings (signals growth).
5. If you need more data on any topic, keep searching. Stop when you have enough.

When you have sufficient information, return ONLY valid JSON (no markdown, no code fences):
{
  "companyName": string,
  "industry": string,
  "hq": string,
  "employeeCount": string,
  "fleetSize": string,
  "summary": string,
  "recentNews": [{"headline": string, "relevance": string}],
  "painPoints": [string],
  "competitors": [string],
  "productMatches": [{"product": string, "reason": string, "value": string}],
  "focus": string,
  "topProduct": string,
  "topPainPoint": string,
  "recentEvent": string,
  "score": number,
  "linkedinSignals": [string],
  "industryTrends": [string],
  "hiringSignals": string,
  "fundingOrExpansion": string,
  "displacementAngle": string,
  "decisionMakerHint": string,
  "contactName": string,
  "contactTitle": string,
  "contactEmail": string,
  "contactPhone": string,
  "currentFleetPlatform": string,
  "trackableAssets": [string]
}`;

// ── Agentic loop ─────────────────────────────────────────────────────────────
const messages = [
  { role: 'user', parts: [{ text: RESEARCH_PROMPT }] },
];

for (let round = 0; round < MAX_ROUNDS; round++) {
  const resp = await callGemini(messages);
  const candidate = resp.candidates?.[0];

  if (!candidate?.content) {
    throw new Error('Gemini returned no candidate: ' + JSON.stringify(resp).slice(0, 300));
  }

  // Add Gemini's reply to message history
  messages.push(candidate.content);

  const parts = candidate.content.parts || [];
  const toolCalls = parts.filter(p => p.functionCall);
  const textParts = parts.filter(p => p.text);

  // If Gemini returned text with no tool calls → it has its answer
  if (!toolCalls.length && textParts.length) {
    const text = textParts.map(p => p.text).join('');
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return [{ json: JSON.parse(match[0]) }];
      } catch (e) {
        return [{ json: { error: 'JSON parse failed: ' + e.message, raw: text.slice(0, 500) } }];
      }
    }
    // No JSON found — surface the raw text so the Python fallback can handle it
    return [{ json: { error: 'No JSON block in final response', raw: text.slice(0, 500), companyName: company_name } }];
  }

  // Execute tool calls and build function response parts
  const functionResponseParts = [];
  for (const part of toolCalls) {
    const { name, args } = part.functionCall;
    let result;
    try {
      result = await executeTool(name, args);
    } catch (e) {
      result = `Error executing ${name}: ${e.message}`;
    }
    functionResponseParts.push({
      functionResponse: { name, response: { result } },
    });
  }

  // Feed tool results back as a function role message
  messages.push({ role: 'function', parts: functionResponseParts });
}

return [{ json: { error: 'Max research rounds reached', companyName: company_name } }];
